import { evidence, type ITtscEvidenceGraphConfig, type ITtscEvidenceGraphMarkdownReference, type ITtscEvidenceGraphReferenceBase } from "@ttsc/evidence";

// Keep independent public policies on separate references: combining checklist
// with either cardinality flag is rejected during native configuration decoding.
const reference: ITtscEvidenceGraphMarkdownReference = {
  type: "markdown", files: ["docs/**/*.md"], symbol: "h2",
  noEvidenceExclude: true,
  uniqueEvidence: true,
  singleEvidencePerSymbol: true,
};
const base: ITtscEvidenceGraphReferenceBase<"markdown"> = reference;
void base;
const graph: ITtscEvidenceGraphConfig = { claims: [{
  type: "typescript", name: "Order contract", files: ["src/**/*.ts"],
  symbol: "function", reference,
}, {
  type: "typescript", name: "Order checklist", files: ["src/**/*.ts"],
  symbol: "function", reference: {
    type: "markdown", files: ["docs/**/*.md"], symbol: "h2", checklist: true,
  },
}] };
export default { plugins: { evidence }, rules: { "evidence/graph": ["error", graph] } } satisfies ITtscLintConfig;

